type Client = { id: number; projectId?: number | null; clientId?: string | null; clientName: string; clientOwnerName: string; contactNumber: string; email: string; address: string; noOfStudents: number; pricingMode: "perStudent" | "package"; perStudentPrice: string | null; packagePrice: string | null; price?: string | null; gstRate?: string | null; gstMode?: "inclusive" | "exclusive" | null; gstAmount?: string | null; session: string; startDate: string; endDate: string; totalPrice: string; description: string | null; instituteType: "School" | "College" | "Academy"; branchCoverage: "individual" | "multiple"; branchCount: number; paymentTrackingStartedAt?: string | Date | null; clientStatus?: ClientManualStatus | null; status?: ClientManualStatus; createdAt?: string | Date; updatedAt?: string | Date };
type Term = { label: string; dueDate: string; amount: string };
type Product = { id?: number; productName: string; description: string; quantity: string; unitPrice: string; gstRate: string; gstMode: "inclusive" | "exclusive"; paidAmount: string; originalPaidAmount?: string; dueDate: string; paymentDate: string; paymentMode: string; transactionReference: string; totalAmount?: string; gstAmount?: string; paymentStatus?: "Pending" | "Partially Paid" | "Paid" };
type ReceiptDraft = { productIndex: number; amount: string; receiptDate: string; paymentDate: string; paymentMode: "Cash" | "UPI" | "Bank Transfer" | "Card" | "Cheque" | "Other"; transactionReference: string; notes: string };
type Cycle = "single" | "terms" | "installments" | "months";

function money(value: number | string | null | undefined) { return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", currencyDisplay: "narrowSymbol", maximumFractionDigits: 0 }).format(Number(value ?? 0)); }
function todayIso() { return new Date().toISOString().slice(0, 10); }
function amountInWords(value: number) { if (!Number.isFinite(value) || value <= 0) return "Rupees Zero Only"; const rounded = Math.round(value * 100) / 100; const rupees = Math.floor(rounded); const paise = Math.round((rounded - rupees) * 100); const ones = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]; const tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]; const chunk = (number: number): string => number < 20 ? ones[number] : number < 100 ? tens[Math.floor(number / 10)] + (number % 10 ? ` ${ones[number % 10]}` : "") : `${ones[Math.floor(number / 100)]} Hundred${number % 100 ? ` ${chunk(number % 100)}` : ""}`; let remaining = rupees; const parts: string[] = []; const crore = Math.floor(remaining / 10000000); if (crore) { parts.push(`${chunk(crore)} Crore`); remaining %= 10000000; } const lakh = Math.floor(remaining / 100000); if (lakh) { parts.push(`${chunk(lakh)} Lakh`); remaining %= 100000; } const thousand = Math.floor(remaining / 1000); if (thousand) { parts.push(`${chunk(thousand)} Thousand`); remaining %= 1000; } if (remaining) parts.push(chunk(remaining)); return `Rupees ${parts.join(" ") || "Zero"}${paise ? ` and ${paise}/100 Paise` : ""} Only`; }
function addMonths(dateValue: string, months: number) { const date = new Date(`${dateValue}T00:00:00`); date.setMonth(date.getMonth() + months); return date.toISOString().slice(0, 10); }
function formatDate(value: string | null | undefined) { return value ? new Date(`${value}T00:00:00`).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }) : "—"; }
function statusClass(status: string) { return status === "Active" ? "bg-emerald-100 text-emerald-700" : status === "Hold" ? "bg-amber-100 text-amber-700" : status === "Cancelled" || status === "Closed" ? "bg-slate-200 text-slate-700" : "bg-blue-100 text-blue-700"; }
function gstBreakdown(amount: number, rate: number, mode: "inclusive" | "exclusive") { const safeRate = Math.max(rate, 0); if (mode === "inclusive") { const taxable = safeRate > 0 ? amount / (1 + safeRate / 100) : amount; return { taxable, gst: amount - taxable, total: amount }; } const gst = amount * safeRate / 100; return { taxable: amount, gst, total: amount + gst }; }
function productBreakdown(product: Product) { return gstBreakdown(Number(product.quantity || 0) * Number(product.unitPrice || 0), Number(product.gstRate || 0), product.gstMode); }
function productTotal(product: Product) { return productBreakdown(product).total; }
function productPaid(product: Product) { return Math.min(Math.max(Number(product.paidAmount || 0), 0), productTotal(product)); }
function paymentPosition(client: Client, invoices: any[], receipts: any[], products: Product[] = []) { const matches = (row: any) => client.clientId && row.clientId ? String(row.clientId).toLowerCase() === String(client.clientId).toLowerCase() : String(row.clientName ?? "").trim().toLowerCase() === client.clientName.trim().toLowerCase(); const clientInvoices = invoices.filter((row) => matches(row) && recordBelongsToClientCycle(row, client, "invoiceDate")); const clientReceipts = receipts.filter((row) => matches(row) && row.status !== "Cancelled" && recordBelongsToClientCycle(row, client, "paymentDate")); const receiptInvoiceIds = new Set(clientReceipts.map((row) => row.invoiceId).filter(Boolean)); const paidInvoices = clientInvoices.filter((row) => row.status === "Paid" && !receiptInvoiceIds.has(row.id)); const paid = clientReceipts.reduce((sum, row) => sum + Number(row.amount ?? row.grandTotal ?? 0), 0) + paidInvoices.reduce((sum, row) => sum + Number(row.grandTotal ?? 0), 0); const currentProducts = currentCycleProducts(products, client.paymentTrackingStartedAt); return clientPaymentPosition(client, currentProducts.map(productTotal), paid); }

export default function ClientPaymentPlan() {
  const params = useParams<{ id: string }>();
  const [, navigate] = useLocation();
  const auth = trpc.auth.me.useQuery();
  const clientsQuery = trpc.clients.list.useQuery({ page: 1, pageSize: 1000, sessionMode: "all", currentSession: "2026-2027" }, { enabled: Boolean(auth.data) });
  const invoicesQuery = trpc.invoices.list.useQuery(undefined, { enabled: Boolean(auth.data) });
  const receiptsQuery = trpc.receipts.list.useQuery(undefined, { enabled: Boolean(auth.data) });
  const projectsQuery = trpc.projects.list.useQuery(undefined, { enabled: Boolean(auth.data) });
  const client = useMemo(() => (clientsQuery.data?.items as Client[] | undefined)?.find((item) => Math.abs(item.id) === Math.abs(Number(params.id))) ?? null, [clientsQuery.data?.items, params.id]);
  const [products, setProducts] = useState<Product[]>([]);
  const planQuery = trpc.clients.paymentPlan.useQuery({ clientId: client?.clientId ?? "" }, { enabled: Boolean(client?.clientId) });
  const productsQuery = trpc.clients.products.useQuery({ clientId: client?.clientId ?? "" }, { enabled: Boolean(client?.clientId) });
  const utils = trpc.useUtils();
  const savePlan = trpc.clients.savePaymentPlan.useMutation({ onSuccess: async () => { await planQuery.refetch(); toast.success("Payment reminder schedule saved."); }, onError: (error) => toast.error(error.message) });
  const saveProducts = trpc.clients.saveProducts.useMutation({ onSuccess: async () => { await productsQuery.refetch(); await utils.clients.list.invalidate(); toast.success("Products and payment details saved."); }, onError: (error) => toast.error(error.message) });
  const [receiptDraft, setReceiptDraft] = useState<ReceiptDraft | null>(null);
  const createReceipt = trpc.receipts.create.useMutation({ onSuccess: async () => { setReceiptDraft(null); await saveProductDetails(); toast.success("Receipt submitted and product payment updated."); }, onError: (error) => toast.error(error.message) });
  const updateClient = trpc.clients.update.useMutation({ onSuccess: async () => { await utils.clients.list.invalidate(); toast.success("Client details updated."); }, onError: (error) => toast.error(error.message) });
  const [renewalOpen, setRenewalOpen] = useState(false);
  const [renewalType, setRenewalType] = useState<"continuous" | "sixMonths" | "oneYear">("continuous");
  const [renewalStartDate, setRenewalStartDate] = useState("");
  const [renewalEndDate, setRenewalEndDate] = useState("");
  const [renewalLink, setRenewalLink] = useState("");
  const [extensionOpen, setExtensionOpen] = useState(false);
  const [extensionEndDate, setExtensionEndDate] = useState("");
  const renewAgreement = trpc.agreements.renew.useMutation({ onSuccess: async (agreement) => { await utils.clients.list.invalidate(); const link = `${window.location.origin}/agreement/${agreement.publicToken}`; setRenewalLink(link); try { await navigator.clipboard?.writeText(link); toast.success("Renewal agreement created; link copied."); } catch { toast.success("Renewal agreement created. Share the link below."); } }, onError: (error) => toast.error(error.message) });
  const renewDirectClient = trpc.clients.renewDirect.useMutation({ onSuccess: async () => { setRenewalOpen(false); await utils.clients.list.invalidate(); await clientsQuery.refetch(); toast.success("Client renewal dates updated with the same Client ID."); }, onError: (error) => toast.error(error.message) });
  const extendExpiry = trpc.agreements.extend.useMutation({ onSuccess: async () => { setExtensionOpen(false); await utils.clients.list.invalidate(); await clientsQuery.refetch(); toast.success("Current plan expiry date extended."); }, onError: (error) => toast.error(error.message) });
  const projects = projectsQuery.data ?? [];
  const selectedProject = projects.find((project) => project.id === client?.projectId);
  useEffect(() => {
    if (!client) return;
    const dates = renewalDates({ previousStartDate: client.startDate, previousEndDate: client.endDate, planYears: 1, renewalType, today: todayIso() });
    setRenewalStartDate(dates.startDate);
    setRenewalEndDate(dates.endDate);
  }, [client?.id, renewalType]);
  const renewalGapReason = useMemo(() => client ? renewalReason({ previousEndDate: client.endDate, renewalType, today: todayIso(), startDate: renewalStartDate }) : "", [client?.endDate, renewalStartDate, renewalType]);
  const isMainProject = Boolean(selectedProject?.isMain);
  const statusOptions = getManualClientStatuses(isMainProject);
  const [cycle, setCycle] = useState<Cycle>("installments");
  const cycleLabel = cycle === "terms" ? "Terms" : cycle === "months" ? "Months" : "Installments";
  const cycleUnit = cycle === "terms" ? "Term" : cycle === "months" ? "Month" : "Installment";
  const handleCycleChange = (next: Cycle) => {
    setCycle(next);
    if (next === "single") return;
    setTerms((current) => {
      const states = getPaymentTermStates(current, payment?.paid ?? 0);
      return current.map((term, index) => states[index]?.isPaid ? term : (/^(Term|Month|Installment)\s+\d+$/i.test(term.label) ? { ...term, label: `${next === "terms" ? "Term" : next === "months" ? "Month" : "Installment"} ${index + 1}` } : term));
    });
  };
  const [totalAmount, setTotalAmount] = useState("");
  const [initialPayment, setInitialPayment] = useState("");
  const [terms, setTerms] = useState<Term[]>([]);
  const [clientForm, setClientForm] = useState({ clientName: "", clientOwnerName: "", contactNumber: "", email: "", address: "", status: "Active" as ClientManualStatus, pricingMode: "package" as "perStudent" | "package", noOfStudents: "0", perStudentPrice: "0", packagePrice: "0", gstRate: "18", gstMode: "exclusive" as "inclusive" | "exclusive" });
  const primaryLabel = isMainProject ? "ERP primary" : selectedProject?.name ?? "Primary project";
  const primaryPricing = isMainProject ? calculateErpPricing({ mode: clientForm.pricingMode, noOfStudents: Number(clientForm.noOfStudents || 0), perStudentPrice: Number(clientForm.perStudentPrice || 0), packagePrice: Number(clientForm.packagePrice || 0), fallbackPrice: Number(client?.price ?? client?.totalPrice ?? 0), gstRate: Number(clientForm.gstRate || 0), gstMode: clientForm.gstMode }) : null;
  const primarySubtotal = primaryPricing?.entered ?? Number(client?.price ?? 0);
  const primaryFallbackBreakdown = gstBreakdown(primarySubtotal, Number(clientForm.gstRate || 0), clientForm.gstMode);
  const primaryBreakdown = { taxable: primarySubtotal, gst: primaryPricing?.gstAmount ?? primaryFallbackBreakdown.gst, total: primaryPricing?.totalPrice ?? primaryFallbackBreakdown.total };
  const primaryTotal = clientPrimaryTotal({ price: client?.price, gstAmount: client?.gstAmount, gstMode: clientForm.gstMode, totalPrice: primaryBreakdown.total });
  const paymentProducts = products;
  const productsPaid = paymentProducts.reduce((sum, product) => sum + productPaid(product), 0);
  const payment = client ? paymentPosition(client, invoicesQuery.data ?? [], receiptsQuery.data ?? [], paymentProducts) : null;
  const termStates = useMemo(() => getPaymentTermStates(terms, payment?.paid ?? 0), [terms, payment?.paid]);
  const openReminderTerms = useMemo(() => filterOpenPaymentTerms(terms, payment?.paid ?? 0), [terms, payment?.paid]);
  const primaryPaid = Math.min(Math.max((payment?.paid ?? 0) - productsPaid, 0), primaryTotal);
  const primaryPending = Math.max(primaryTotal - primaryPaid, 0);
  const [initializedFor, setInitializedFor] = useState<string | null>(null);
  const [productsInitializedFor, setProductsInitializedFor] = useState<string | null>(null);

  useEffect(() => {
    if (!client?.clientId || productsQuery.isLoading || productsInitializedFor === client.clientId) return;
    setProducts((productsQuery.data ?? []).map((product) => ({ id: product.id, productName: product.productName, description: product.description ?? "", quantity: String(Number(product.quantity)), unitPrice: String(Number(product.unitPrice)), gstRate: String(Number(product.gstRate)), gstMode: product.gstMode, paidAmount: String(Number(product.paidAmount)), originalPaidAmount: String(Number(product.paidAmount)), dueDate: product.dueDate ?? "", paymentDate: product.paymentDate ?? "", paymentMode: product.paymentMode ?? "", transactionReference: product.transactionReference ?? "", totalAmount: String(Number(product.totalAmount)), gstAmount: String(Number(product.gstAmount)), paymentStatus: product.paymentStatus })));
    setProductsInitializedFor(client.clientId);
  }, [client?.clientId, productsQuery.data, productsQuery.isLoading, productsInitializedFor]);

  useEffect(() => {
    if (!client) return;
    if (client.clientId && planQuery.isLoading) return;
    const key = `${client.id}-${client.clientId ?? ""}-${client.startDate}-${client.endDate}-${client.totalPrice}-${client.paymentTrackingStartedAt ? String(client.paymentTrackingStartedAt) : ""}`;
    if (initializedFor === key) return;
    const saved = planQuery.data;
    const total = Number(client.totalPrice ?? 0);
    const paid = payment?.paid ?? 0;
    setCycle(saved?.paymentCycle ?? "installments");
    setTotalAmount(String(Number(saved?.totalAmount ?? total)));
    setInitialPayment(String(Number(saved?.initialPayment ?? Math.min(paid, total))));
    setTerms(saved?.terms?.length ? saved.terms.map((term) => ({ label: term.label, dueDate: term.dueDate, amount: String(Number(term.amount)) })) : [{ label: "Installment 1", dueDate: client.endDate || addMonths(todayIso(), 1), amount: String(Math.max(total - Math.min(paid, total), 0)) }]);
    setClientForm({ clientName: client.clientName, clientOwnerName: client.clientOwnerName, contactNumber: client.contactNumber, email: client.email, address: client.address, status: client.clientStatus ?? client.status ?? "Active", pricingMode: client.pricingMode ?? "package", noOfStudents: String(client.noOfStudents ?? 0), perStudentPrice: String(Number(client.perStudentPrice ?? 0)), packagePrice: String(Number(client.packagePrice ?? client.price ?? client.totalPrice ?? 0)), gstRate: String(Number(client.gstRate ?? 18)), gstMode: client.gstMode ?? "exclusive" });
    setInitializedFor(key);
  }, [client, payment?.paid, planQuery.data, planQuery.isLoading, initializedFor]);

  const remaining = calculateRemainingPayment(Number(totalAmount || 0), Number(initialPayment || 0));
  const scheduled = terms.reduce((sum, term) => sum + Number(term.amount || 0), 0);
  const scheduleDifference = calculateScheduleDifference(terms, remaining);
  const updateTerm = (index: number, key: keyof Term, value: string) => setTerms((current) => getPaymentTermStates(current, payment?.paid ?? 0)[index]?.isPaid ? current : current.map((term, termIndex) => termIndex === index ? { ...term, [key]: value } : term));
  const addTerm = () => setTerms((current) => [...current, { label: `${cycleUnit} ${current.length + 1}`, dueDate: addMonths(current[current.length - 1]?.dueDate || todayIso(), 1), amount: "0" }]);
  const removeTerm = (index: number) => setTerms((current) => current.length <= 1 || getPaymentTermStates(current, payment?.paid ?? 0)[index]?.isPaid ? current : current.filter((_, termIndex) => termIndex !== index));
  const distributeAmount = () => { if (!terms.length) return; setTerms((current) => distributeRemainingPayment(current, remaining, payment?.paid ?? 0)); };
  const saveSchedule = () => { if (!client?.clientId) return toast.error("This client does not have a Client ID yet."); if (Number(initialPayment) > Number(totalAmount)) return toast.error("Initial payment cannot exceed the assigned total."); if (cycle !== "single" && terms.some((term) => !term.dueDate || Number(term.amount) < 0)) return toast.error(`Complete each ${cycleUnit.toLowerCase()} due date and amount.`); savePlan.mutate({ clientId: client.clientId, projectId: client.projectId ?? null, paymentCycle: cycle, totalAmount: Number(totalAmount || 0), initialPayment: Number(initialPayment || 0), terms: cycle === "single" ? [] : terms.map((term) => ({ ...term, amount: Number(term.amount || 0) })) }); };
  const openExtension = () => { setExtensionEndDate(client?.endDate ?? ""); setExtensionOpen(true); };
  const submitExtension = () => { if (!client || !extensionEndDate) return toast.error("Select a new expiry date."); if (extensionEndDate <= client.endDate) return toast.error("The extended expiry date must be after the current expiry date."); extendExpiry.mutate({ agreementId: client.id, endDate: extensionEndDate }); };
  const saveClientDetails = () => { if (!client) return; if (isMainProject && Number(clientForm.noOfStudents || 0) < 1) return toast.error("Enter the number of students for this ERP client."); const erpPricing = isMainProject ? calculateErpPricing({ mode: clientForm.pricingMode, noOfStudents: Number(clientForm.noOfStudents || 0), perStudentPrice: Number(clientForm.perStudentPrice || 0), packagePrice: Number(clientForm.packagePrice || 0), fallbackPrice: Number(client?.price ?? client?.totalPrice ?? 0), gstRate: Number(clientForm.gstRate || 0), gstMode: clientForm.gstMode }) : null; updateClient.mutate({ id: client.id, clientName: clientForm.clientName, clientOwnerName: clientForm.clientOwnerName, instituteType: client.instituteType, branchCoverage: client.branchCoverage, branchCount: client.branchCount, contactNumber: clientForm.contactNumber, email: clientForm.email, address: clientForm.address, price: erpPricing?.entered ?? Number(client?.price ?? client?.totalPrice ?? 0), pricingMode: isMainProject ? clientForm.pricingMode : "package", noOfStudents: isMainProject ? Number(clientForm.noOfStudents || 0) : 0, perStudentPrice: erpPricing?.perStudentPrice ?? null, packagePrice: erpPricing?.packagePrice ?? Number(client?.price ?? client?.totalPrice ?? 0), gstRate: erpPricing ? Number(clientForm.gstRate || 0) : Number(client.gstRate ?? 18), gstMode: isMainProject ? clientForm.gstMode : client.gstMode ?? "exclusive", startDate: client.startDate, endDate: client.endDate, session: client.session, description: client.description, status: clientForm.status }); };
  const emptyProduct = (): Product => ({ productName: "", description: "", quantity: "1", unitPrice: "0", gstRate: "0", gstMode: "exclusive", paidAmount: "0", dueDate: "", paymentDate: "", paymentMode: "", transactionReference: "" });
  const updateProduct = (index: number, key: keyof Product, value: string) => setProducts((current) => current.map((product, productIndex) => productIndex === index ? { ...product, [key]: value } : product));
  const saveProductDetails = () => { if (!client?.clientId) return toast.error("This client does not have a Client ID yet."); if (products.some((product) => !product.productName.trim() || Number(product.quantity) <= 0 || Number(product.unitPrice) < 0 || Number(product.paidAmount) < 0)) return toast.error("Complete each product name, quantity, price, and payment amount."); saveProducts.mutate({ clientId: client.clientId, projectId: client.projectId ?? null, products: products.map((product) => ({ productName: product.productName, description: product.description || null, quantity: Number(product.quantity || 0), unitPrice: Number(product.unitPrice || 0), gstRate: Number(product.gstRate || 0), gstMode: product.gstMode, paidAmount: Number(product.paidAmount || 0), dueDate: product.dueDate || null, paymentDate: product.paymentDate || null, paymentMode: product.paymentMode || null, transactionReference: product.transactionReference || null })) }); };
  const prepareReceipt = (productIndex: number) => { const product = products[productIndex]; if (!product || !client?.clientId) return; const collection = calculateReceiptCollectionDelta(Number(product.paidAmount || 0), Number(product.originalPaidAmount || 0), productTotal(product)); const delta = collection.delta; if (!collection.isNewCollection) return toast.error(collection.isOverCollection ? "The collected amount cannot exceed the remaining product balance." : "Enter a new collected amount above the previously recorded payment."); setReceiptDraft({ productIndex, amount: delta.toFixed(2), receiptDate: todayIso(), paymentDate: todayIso(), paymentMode: product.paymentMode === "UPI" || product.paymentMode === "Cash" || product.paymentMode === "Bank Transfer" || product.paymentMode === "Card" || product.paymentMode === "Cheque" || product.paymentMode === "Other" ? product.paymentMode : "Bank Transfer", transactionReference: product.transactionReference, notes: `Partial payment for ${product.productName}` }); };
  const submitReceiptDraft = () => { if (!receiptDraft || !client) return; const product = products[receiptDraft.productIndex]; if (!product || !receiptDraft.amount || Number(receiptDraft.amount) <= 0) return toast.error("Enter a valid collected amount."); createReceipt.mutate({ clientId: client.clientId ?? undefined, clientName: client.clientName, clientAddress: client.address, clientContact: client.contactNumber, clientEmail: client.email || undefined, clientGst: undefined, receiptDate: receiptDraft.receiptDate, paymentDate: receiptDraft.paymentDate, gstRate: 0, gstMode: "exclusive", paymentMode: receiptDraft.paymentMode, transactionReference: receiptDraft.transactionReference || undefined, notes: receiptDraft.notes || undefined, items: [{ itemName: product.productName, description: product.description || `Payment collected against ${product.productName}`, quantity: 1, unitPrice: Number(receiptDraft.amount) }] }); };

  if (clientsQuery.isLoading || !auth.data) return <DashboardLayout><div className="flex min-h-[calc(100vh-6rem)] items-center justify-center bg-[#f7f8fc]"><Loader2 className="h-7 w-7 animate-spin text-[#3157d5]" /></div></DashboardLayout>;
  if (!client) return <DashboardLayout><main className="min-h-[calc(100vh-6rem)] bg-[#f7f8fc] p-6"><Button variant="outline" onClick={() => navigate("/clients")}><ArrowLeft className="mr-2 h-4 w-4" />Back to Clients</Button><div className="mt-12 text-center text-slate-500">Client not found.</div></main></DashboardLayout>;

  return <DashboardLayout><main className="min-h-[calc(100vh-6rem)] bg-[#f7f8fc] p-4 text-[#172033] sm:p-6 lg:p-8"><div className="mx-auto max-w-7xl space-y-6"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><Button variant="ghost" className="mb-3 -ml-3 text-slate-500" onClick={() => navigate("/clients")}><ArrowLeft className="mr-2 h-4 w-4" />Back to Clients</Button><div className="flex flex-wrap items-center gap-3"><h1 className="font-serif text-4xl tracking-tight text-[#172033] sm:text-5xl">Edit client payment plan</h1><Badge className={statusClass(clientForm.status)}>{clientForm.status}</Badge></div><p className="mt-2 text-sm text-slate-500">Manage client details, payment reminders, and instalment distribution without changing how invoices or receipts are collected.</p></div><div className="flex flex-wrap items-center gap-2">{(isMainProject || client.id < 0) && <Button type="button" variant="outline" className="border-[#cfc5ff] text-[#4f2ad3]" onClick={() => { setRenewalLink(""); setRenewalOpen(true); }}><RefreshCw className="mr-2 h-4 w-4" />Renewal</Button>}{!isMainProject && <Button type="button" variant="outline" className="border-amber-200 text-amber-700" onClick={openExtension}><CalendarDays className="mr-2 h-4 w-4" />Extend expiry</Button>}<div className="rounded-2xl border border-[#ddd8ff] bg-white px-5 py-4 shadow-sm"><p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-400">Client ID</p><p className="mt-1 text-xl font-bold text-[#4f2ad3]">{client.clientId ?? `ERP${Math.abs(client.id)}`}</p><p className="mt-1 text-xs text-slate-500">{client.clientName}</p></div><div className="rounded-2xl border border-slate-200 bg-white px-4 py-3 shadow-sm"><p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-400">Current plan</p><div className="mt-1 flex items-center gap-3 text-sm"><span><span className="text-slate-400">From</span> <strong className="text-slate-800">{formatDate(client.startDate)}</strong></span><span className="text-slate-300">→</span><span><span className="text-slate-400">To</span> <strong className="text-orange-600">{formatDate(client.endDate)}</strong></span></div></div></div></div>
    <div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><Card className="border-0 shadow-[0_18px_60px_rgba(30,45,80,0.07)]"><CardHeader><CardTitle className="flex items-center gap-2 font-serif text-2xl"><CreditCard className="h-5 w-5 text-[#4f2ad3]" />Payment position</CardTitle></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded-xl bg-[#f4f1ff] p-4"><p className="text-[10px] uppercase tracking-wide text-slate-400">Assigned total</p><p className="mt-2 text-xl font-bold text-[#4f2ad3]">{money(payment?.total)}</p></div><div className="rounded-xl bg-emerald-50 p-4"><p className="text-[10px] uppercase tracking-wide text-slate-400">Total paid</p><p className="mt-2 text-xl font-bold text-emerald-600">{money(payment?.paid)}</p></div><div className="rounded-xl bg-rose-50 p-4"><p className="text-[10px] uppercase tracking-wide text-slate-400">Total pending</p><p className="mt-2 text-xl font-bold text-rose-600">{money(payment?.due)}</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-[10px] uppercase tracking-wide text-slate-400">Progress</p><p className="mt-2 text-xl font-bold text-slate-700">{Math.round(payment?.progress ?? 0)}%</p></div></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-[#6555e8]" style={{ width: `${payment?.progress ?? 0}%` }} /></div><div className="mt-5 rounded-2xl border border-indigo-100 bg-indigo-50/60 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.12em] text-indigo-500">{primaryLabel}</p><p className="mt-1 text-lg font-bold text-indigo-950">Primary product financial details</p></div><p className="text-xl font-bold text-indigo-700">{money(primaryTotal)}</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Taxable amount</p><p className="mt-1 font-semibold text-slate-800">{money(primaryBreakdown.taxable)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">GST ({clientForm.gstRate}%)</p><p className="mt-1 font-semibold text-slate-800">{money(primaryBreakdown.gst)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">GST mode</p><p className="mt-1 font-semibold capitalize text-slate-800">{clientForm.gstMode}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Total</p><p className="mt-1 font-semibold text-indigo-700">{money(primaryTotal)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Paid</p><p className="mt-1 font-semibold text-emerald-600">{money(primaryPaid)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Pending</p><p className="mt-1 font-semibold text-rose-600">{money(primaryPending)}</p></div></div></div>{products.length > 0 && <div className="mt-4 space-y-3"><p className="text-xs font-bold uppercase tracking-[0.12em] text-slate-500">Additional products</p>{products.map((product, index) => { const breakdown = productBreakdown(product); const total = breakdown.total; const paid = productPaid(product); const pending = Math.max(total - paid, 0); return <div key={product.id ?? `payment-product-${index}`} className="rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.12em] text-slate-400">Product {index + 1}</p><p className="mt-1 font-semibold text-slate-800">{product.productName || "Unnamed product"}</p></div><p className="text-lg font-bold text-slate-800">{money(total)}</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Taxable amount</p><p className="mt-1 font-semibold text-slate-800">{money(breakdown.taxable)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">GST ({product.gstRate}%)</p><p className="mt-1 font-semibold text-slate-800">{money(breakdown.gst)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">GST mode</p><p className="mt-1 font-semibold capitalize text-slate-800">{product.gstMode}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Total</p><p className="mt-1 font-semibold text-slate-800">{money(total)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Paid</p><p className="mt-1 font-semibold text-emerald-600">{money(paid)}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-500">Pending</p><p className="mt-1 font-semibold text-rose-600">{money(pending)}</p></div></div></div>; })}</div>}<p className="mt-4 flex items-center gap-2 text-xs text-slate-500"><Wallet className="h-4 w-4 text-[#4f2ad3]" />Invoices and receipts may collect any amount; this schedule is used only for reminders.</p></CardContent></Card>
      <Card className="border-0 shadow-[0_18px_60px_rgba(30,45,80,0.07)]"><CardHeader><CardTitle className="font-serif text-2xl">Client details</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><div><Label>Client name</Label><Input className="mt-1.5" value={clientForm.clientName} onChange={(event) => setClientForm((form) => ({ ...form, clientName: event.target.value }))} /></div><div><Label>Client owner name</Label><Input className="mt-1.5" value={clientForm.clientOwnerName} onChange={(event) => setClientForm((form) => ({ ...form, clientOwnerName: event.target.value }))} /></div><div><Label>Phone</Label><Input className="mt-1.5" value={clientForm.contactNumber} onChange={(event) => setClientForm((form) => ({ ...form, contactNumber: event.target.value }))} /></div><div><Label>Email</Label><Input type="email" className="mt-1.5" value={clientForm.email} onChange={(event) => setClientForm((form) => ({ ...form, email: event.target.value }))} /></div><div className="sm:col-span-2"><Label>Address</Label><Textarea className="mt-1.5" value={clientForm.address} onChange={(event) => setClientForm((form) => ({ ...form, address: event.target.value }))} /></div><div><Label>Project</Label><Input className="mt-1.5 bg-slate-50" value={projects.find((project) => project.id === client.projectId)?.name ?? "—"} readOnly /></div>{isMainProject && <><div><Label>ERP pricing mode</Label><select className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={clientForm.pricingMode} onChange={(event) => setClientForm((form) => ({ ...form, pricingMode: event.target.value as "perStudent" | "package" }))}><option value="perStudent">Per Student</option><option value="package">Package</option></select></div><><div><Label>No. of students</Label><Input className="mt-1.5" type="number" min="1" value={clientForm.noOfStudents} onChange={(event) => setClientForm((form) => ({ ...form, noOfStudents: event.target.value }))} required /></div>{clientForm.pricingMode === "perStudent" ? <div><Label>Per student price</Label><Input className="mt-1.5" type="number" min="0" step="0.01" value={clientForm.perStudentPrice} onChange={(event) => setClientForm((form) => ({ ...form, perStudentPrice: event.target.value }))} /></div> : <div><Label>Package price</Label><Input className="mt-1.5" type="number" min="0" step="0.01" value={clientForm.packagePrice} onChange={(event) => setClientForm((form) => ({ ...form, packagePrice: event.target.value }))} /> </div>}</><div><Label>GST rate (%)</Label><Input className="mt-1.5" type="number" min="0" value={clientForm.gstRate} onChange={(event) => setClientForm((form) => ({ ...form, gstRate: event.target.value }))} /></div><div><Label>GST mode</Label><select className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={clientForm.gstMode} onChange={(event) => setClientForm((form) => ({ ...form, gstMode: event.target.value as "inclusive" | "exclusive" }))}><option value="exclusive">GST Exclusive</option><option value="inclusive">GST Inclusive</option></select></div></>}<div><Label>Status</Label><select className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={clientForm.status} onChange={(event) => setClientForm((form) => ({ ...form, status: event.target.value as ClientManualStatus }))}>{statusOptions.map((status) => <option key={status} value={status}>{status}</option>)}</select></div><div className="sm:col-span-2 flex justify-end"><Button onClick={saveClientDetails} disabled={updateClient.isPending}><Save className="mr-2 h-4 w-4" />{updateClient.isPending ? "Saving…" : "Save client details"}</Button></div></CardContent></Card></div>
      <Card className="border-0 shadow-[0_18px_60px_rgba(30,45,80,0.07)]"><CardHeader className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="flex items-center gap-2 font-serif text-2xl"><Plus className="h-5 w-5 text-[#4f2ad3]" />Products and services</CardTitle><p className="mt-1 text-sm text-slate-500">Add products taken by this client and record product-level payment details. These totals roll into the payment position above.</p></div><Button variant="outline" onClick={() => setProducts((current) => [...current, emptyProduct()])}><Plus className="mr-2 h-4 w-4" />Add product</Button></CardHeader><CardContent>{products.length === 0 ? <div className="rounded-2xl border border-dashed border-[#c9c2ff] bg-[#faf9ff] p-6 text-center"><p className="font-semibold text-slate-800">No products added</p><p className="mt-1 text-sm text-slate-500">Add a service or product when the client takes something beyond the base agreement.</p></div> : <div className="space-y-4">{products.map((product, index) => <div key={product.id ?? `new-${index}`} className="rounded-2xl border border-slate-200 bg-slate-50/60 p-4"><div className="mb-4 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-slate-400">Product {index + 1}</p><p className="mt-1 font-semibold text-slate-800">{product.productName || "New product"}</p></div><Button variant="ghost" size="icon" onClick={() => setProducts((current) => current.filter((_, productIndex) => productIndex !== index))} aria-label={`Remove product ${index + 1}`}><Trash2 className="h-4 w-4 text-rose-500" /></Button></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><div className="xl:col-span-2"><Label>Product / service name</Label><Input className="mt-1.5" value={product.productName} onChange={(event) => updateProduct(index, "productName", event.target.value)} placeholder="e.g. Annual support" /></div><div><Label>Quantity</Label><Input className="mt-1.5" type="number" min="0.01" step="0.01" value={product.quantity} onChange={(event) => updateProduct(index, "quantity", event.target.value)} /></div><div><Label>Unit price</Label><Input className="mt-1.5" type="number" min="0" step="0.01" value={product.unitPrice} onChange={(event) => updateProduct(index, "unitPrice", event.target.value)} /></div><div><Label>GST rate (%)</Label><Input className="mt-1.5" type="number" min="0" max="100" step="0.01" value={product.gstRate} onChange={(event) => updateProduct(index, "gstRate", event.target.value)} /></div><div><Label>GST mode</Label><select className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={product.gstMode} onChange={(event) => updateProduct(index, "gstMode", event.target.value as Product["gstMode"])}><option value="exclusive">Exclusive</option><option value="inclusive">Inclusive</option></select></div><div><Label>Paid amount</Label><Input className="mt-1.5" type="number" min="0" step="0.01" value={product.paidAmount} onChange={(event) => updateProduct(index, "paidAmount", event.target.value)} /></div><div><Label>Due date</Label><Input className="mt-1.5" type="date" value={product.dueDate} onChange={(event) => updateProduct(index, "dueDate", event.target.value)} /></div><div><Label>Payment date</Label><Input className="mt-1.5" type="date" value={product.paymentDate} onChange={(event) => updateProduct(index, "paymentDate", event.target.value)} /></div><div><Label>Payment mode</Label><Input className="mt-1.5" value={product.paymentMode} onChange={(event) => updateProduct(index, "paymentMode", event.target.value)} placeholder="UPI / Bank / Cash" /></div><div><Label>Transaction reference</Label><Input className="mt-1.5" value={product.transactionReference} onChange={(event) => updateProduct(index, "transactionReference", event.target.value)} /></div><div className="xl:col-span-2"><Label>Description / notes</Label><Input className="mt-1.5" value={product.description} onChange={(event) => updateProduct(index, "description", event.target.value)} /></div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 pt-3 text-sm"><span className="text-slate-500">Status: <strong className="text-slate-700">{productPaid(product) >= productTotal(product) ? "Paid" : productPaid(product) > 0 ? "Partially Paid" : "Pending"}</strong></span><span className="font-semibold text-[#4f2ad3]">Product total: {money(productTotal(product))}</span><span className="font-semibold text-emerald-600">Paid: {money(productPaid(product))}</span><Button variant="outline" size="sm" onClick={() => prepareReceipt(index)} disabled={createReceipt.isPending || Number(product.paidAmount || 0) <= Number(product.originalPaidAmount || 0)}><ReceiptText className="mr-1.5 h-4 w-4" />Prepare receipt</Button></div></div>)}</div>}<div className="mt-5 flex flex-col justify-between gap-3 border-t border-slate-100 pt-5 sm:flex-row sm:items-center"><p className="text-xs text-slate-500">Product totals are added to Assigned Total. Invoice and Receipt collections remain separate actual-collection records.</p><Button onClick={saveProductDetails} disabled={saveProducts.isPending}><Save className="mr-2 h-4 w-4" />{saveProducts.isPending ? "Saving…" : "Save products"}</Button></div></CardContent></Card>
      <Card className="border-0 shadow-[0_18px_60px_rgba(30,45,80,0.07)]"><CardHeader className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="font-serif text-2xl">Payment schedule</CardTitle><p className="mt-1 text-sm text-slate-500">Choose one payment or distribute the remaining balance across the selected reminder cycle.</p></div><div className="flex items-center gap-2"><Label htmlFor="payment-cycle" className="sr-only">Payment cycle</Label><select id="payment-cycle" value={cycle} onChange={(event) => handleCycleChange(event.target.value as Cycle)} className="h-10 rounded-xl border border-[#6655e8] bg-white px-3 text-sm font-semibold text-slate-700"><option value="terms">Terms</option><option value="months">Months</option><option value="installments">Installments</option><option value="single">Single payment</option></select></div></CardHeader><CardContent>{cycle === "single" ? <div className="rounded-2xl border border-dashed border-[#c9c2ff] bg-[#faf9ff] p-5"><p className="font-semibold text-slate-800">Single payment reminder</p><p className="mt-1 text-sm text-slate-500">Use the initial payment and one remaining due date. Billing can still collect any invoice or receipt amount.</p><div className="mt-4 grid gap-4 sm:grid-cols-3"><div><Label>Initial payment</Label><Input className="mt-1.5" type="number" min="0" value={initialPayment} onChange={(event) => setInitialPayment(event.target.value)} /></div><div><Label>Remaining amount</Label><Input className="mt-1.5 bg-slate-50" value={money(remaining)} readOnly /></div><div><Label>Due date</Label><Input className="mt-1.5" type="date" value={terms[0]?.dueDate ?? ""} disabled={termStates[0]?.isPaid} onChange={(event) => setTerms([{ label: "Remaining balance", dueDate: event.target.value, amount: String(remaining) }])} />{termStates[0]?.isPaid && <p className="mt-1 text-xs font-semibold text-emerald-600">Paid · locked</p>}</div></div></div> : <><div className="mb-3 flex flex-col gap-3 rounded-2xl bg-[#faf9ff] p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-400">Billing schedule ({cycleLabel})</p><p className="mt-1 text-sm text-slate-500">Remaining to distribute: <strong className="text-[#4f2ad3]">{money(remaining)}</strong></p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={distributeAmount}><Wallet className="mr-1.5 h-4 w-4" />Distribute amount</Button><Button variant="outline" size="sm" onClick={addTerm}><Plus className="mr-1.5 h-4 w-4" />Add {cycleUnit.toLowerCase()}</Button></div></div><div className="overflow-x-auto rounded-2xl border border-slate-200"><div className="grid min-w-[680px] grid-cols-[1.2fr_1fr_1fr_40px] gap-3 bg-slate-50 px-4 py-3 text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400"><span>Label</span><span>Due date</span><span>Amount (₹)</span><span /></div>{terms.map((term, index) => { const isPaid = termStates[index]?.isPaid ?? false; return <div key={`${term.label}-${index}`} className={`grid min-w-[680px] grid-cols-[1.2fr_1fr_1fr_40px] items-center gap-3 border-t border-slate-100 px-4 py-3 ${isPaid ? "bg-emerald-50/60" : ""}`}><div className="flex items-center gap-2"><Input value={term.label} disabled={isPaid} onChange={(event) => updateTerm(index, "label", event.target.value)} />{isPaid && <Badge className="shrink-0 bg-emerald-100 text-emerald-700">Paid · locked</Badge>}</div><Input type="date" value={term.dueDate} disabled={isPaid} onChange={(event) => updateTerm(index, "dueDate", event.target.value)} /><Input type="number" min="0" step="1" value={String(formatWholeRupees(term.amount))} disabled={isPaid} onChange={(event) => updateTerm(index, "amount", event.target.value)} /><Button variant="ghost" size="icon" onClick={() => removeTerm(index)} disabled={terms.length <= 1 || isPaid} aria-label={`Remove ${term.label}`}><Trash2 className="h-4 w-4 text-rose-500" /></Button></div>; })}</div><div className={`mt-3 flex flex-wrap items-center justify-between gap-2 rounded-xl px-4 py-3 text-sm ${Math.abs(scheduleDifference) < 0.01 ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700"}`}><span>{Math.abs(scheduleDifference) < 0.01 ? "Schedule matches the remaining balance." : `Unallocated amount: ${money(scheduleDifference)}`}</span><span className="font-semibold">Initial + {cycleLabel.toLowerCase()}: {money(Number(initialPayment || 0) + scheduled)} / {money(Number(totalAmount || 0))}</span></div></>}{<div className="mt-5 flex flex-col justify-between gap-3 border-t border-slate-100 pt-5 sm:flex-row sm:items-center"><p className="text-xs text-slate-500">Reminder schedule only. Raise invoices or receipts separately for the amount actually collected.</p><Button onClick={saveSchedule} disabled={savePlan.isPending}><Save className="mr-2 h-4 w-4" />{savePlan.isPending ? "Saving…" : "Save payment schedule"}</Button></div>}</CardContent></Card>
      <Card className="border-0 bg-white shadow-[0_18px_60px_rgba(30,45,80,0.07)]"><CardHeader><CardTitle className="flex items-center gap-2 font-serif text-2xl"><CalendarDays className="h-5 w-5 text-[#4f2ad3]" />Upcoming reminders</CardTitle></CardHeader><CardContent>{cycle === "single" || openReminderTerms.length === 0 ? <p className="text-sm text-slate-500">No open {cycleLabel.toLowerCase()} reminders. Closed or fully paid terms are hidden automatically.</p> : <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{openReminderTerms.map((term) => <div key={`reminder-${term.label}-${term.dueDate}`} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-slate-800">{term.label}</p><p className="mt-1 text-xs text-slate-500">Due {formatDate(term.dueDate)}</p></div><Badge className="bg-amber-100 text-amber-700">Reminder</Badge></div><p className="mt-4 text-xl font-bold text-[#4f2ad3]">{money(term.amount)}</p><p className="mt-1 text-xs text-slate-400">Collect any amount through Invoice or Receipt.</p></div>)}</div>}</CardContent></Card>
    </div></main><Dialog open={renewalOpen} onOpenChange={(open) => { setRenewalOpen(open); if (!open) setRenewalLink(""); }}><DialogContent className="w-[min(560px,calc(100vw-2rem))] bg-white text-[#172033]"><DialogHeader><DialogTitle className="font-serif text-2xl">Renew agreement</DialogTitle></DialogHeader>{renewalLink ? <div className="space-y-4"><div className="rounded-xl border border-emerald-100 bg-emerald-50 p-4 text-sm text-emerald-900"><p className="font-semibold">Renewal agreement created</p><p className="mt-1">Client approval is optional. You can share this agreement link or keep it for internal records.</p></div><div><Label htmlFor="client-renewal-link">Agreement link</Label><div className="mt-2 flex gap-2"><Input id="client-renewal-link" value={renewalLink} readOnly className="text-xs" /><Button type="button" variant="outline" size="icon" onClick={async () => { try { await navigator.clipboard.writeText(renewalLink); toast.success("Renewal link copied."); } catch { toast.error("Copy failed. Select and copy the link manually."); } }} title="Copy renewal link" aria-label="Copy renewal link"><ReceiptText className="h-4 w-4" /></Button><a href={renewalLink} target="_blank" rel="noreferrer" className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-slate-200 text-slate-600" title="Open agreement" aria-label="Open agreement"><ExternalLink className="h-4 w-4" /></a></div></div><div className="flex justify-end"><Button type="button" onClick={() => { setRenewalOpen(false); setRenewalLink(""); }}>Done</Button></div></div> : <form onSubmit={(event) => { event.preventDefault(); if (renewalPaymentDue(payment?.total, payment?.paid) > 0.005) { toast.error(`Clear the current plan pending payment of ${money(renewalPaymentDue(payment?.total, payment?.paid))} before renewal.`); return; } if (client.id < 0) { renewDirectClient.mutate({ clientId: Math.abs(client.id), renewalType, startDate: renewalStartDate, endDate: renewalEndDate }); return; } if (!isMainProject) { toast.error("Renewal is available only for an ERP client or an agreement-backed client."); return; } renewAgreement.mutate({ agreementId: client.id, renewalType, startDate: renewalStartDate, endDate: renewalEndDate }); }} className="space-y-5"><div><Label>Renewal start rule</Label><select value={renewalType} onChange={(event) => { const nextType = event.target.value as typeof renewalType; setRenewalType(nextType); const dates = renewalDates({ previousStartDate: client.startDate, previousEndDate: client.endDate, planYears: 1, renewalType: nextType, today: todayIso() }); setRenewalStartDate(dates.startDate); setRenewalEndDate(dates.endDate); }} className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"><option value="continuous">Automatic from expiry gap</option><option value="sixMonths">Six-month gap after current end date</option><option value="oneYear">One-year gap after current end date</option></select></div><div className="grid gap-3 sm:grid-cols-2"><div><Label>Plan From</Label><Input className="mt-1.5" type="date" value={renewalStartDate} onChange={(event) => setRenewalStartDate(event.target.value)} required /></div><div><Label>Plan To</Label><Input className="mt-1.5" type="date" value={renewalEndDate} onChange={(event) => setRenewalEndDate(event.target.value)} required /></div></div><div className="rounded-xl border border-blue-100 bg-blue-50 p-4 text-sm text-blue-900"><p className="font-semibold">Same Client ID and session</p><p className="mt-1">The new agreement keeps all client details and can be opened from the generated link for review. The previous agreement remains in history as Expired.</p><p className="mt-2 font-medium text-blue-800">{renewalGapReason}</p></div><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><Button type="button" variant="outline" onClick={() => setRenewalOpen(false)}>Cancel</Button><Button type="submit" className="bg-[#3157d5] text-white" disabled={renewAgreement.isPending || renewDirectClient.isPending}>{renewAgreement.isPending || renewDirectClient.isPending ? "Saving…" : "Create renewal agreement"}</Button></div></form>}</DialogContent></Dialog><Dialog open={extensionOpen} onOpenChange={setExtensionOpen}><DialogContent className="w-[min(500px,calc(100vw-2rem))] bg-white text-[#172033]"><DialogHeader><DialogTitle className="font-serif text-2xl">Extend expiry date</DialogTitle></DialogHeader><div className="space-y-5"><div className="rounded-xl border border-amber-100 bg-amber-50 p-4 text-sm text-amber-900"><p className="font-semibold">Update the current plan only</p><p className="mt-1">This changes the existing plan expiry date and does not create a new agreement or Client ID.</p><p className="mt-2">Current expiry: <strong>{formatDate(client.endDate)}</strong></p></div><div><Label>New expiry date</Label><Input className="mt-1.5" type="date" min={client.endDate} value={extensionEndDate} onChange={(event) => setExtensionEndDate(event.target.value)} required /></div><div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><Button type="button" variant="outline" onClick={() => setExtensionOpen(false)}>Cancel</Button><Button type="button" className="bg-amber-600 text-white hover:bg-amber-700" onClick={submitExtension} disabled={extendExpiry.isPending}>{extendExpiry.isPending ? "Saving…" : "Save expiry date"}</Button></div></div></DialogContent></Dialog><Dialog open={Boolean(receiptDraft)} onOpenChange={(open) => !open && setReceiptDraft(null)}><DialogContent className="max-h-[90vh] w-[min(780px,calc(100vw-2rem))] overflow-y-auto bg-white text-[#172033]"><DialogHeader><DialogTitle className="flex items-center gap-2 font-serif text-2xl"><ReceiptText className="h-5 w-5 text-[#4f2ad3]" />Receipt draft</DialogTitle></DialogHeader>{receiptDraft && <div className="space-y-5"><div className="rounded-2xl border border-[#ddd8ff] bg-[#faf9ff] p-4"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">Receipt for</p><p className="mt-1 text-lg font-semibold text-slate-800">{products[receiptDraft.productIndex]?.productName}</p><p className="mt-1 text-sm text-slate-500">Client ID: {client.clientId} · {client.clientName}</p><p className="mt-3 text-2xl font-bold text-[#4f2ad3]">{money(receiptDraft.amount)}</p><p className="mt-1 text-xs text-slate-500">Only this newly collected amount will be submitted. The remaining product balance stays pending.</p></div><div className="grid gap-4 sm:grid-cols-2"><div><Label>Receipt date</Label><Input className="mt-1.5" type="date" value={receiptDraft.receiptDate} onChange={(event) => setReceiptDraft((current) => current ? { ...current, receiptDate: event.target.value } : current)} /></div><div><Label>Payment date</Label><Input className="mt-1.5" type="date" value={receiptDraft.paymentDate} onChange={(event) => setReceiptDraft((current) => current ? { ...current, paymentDate: event.target.value } : current)} /></div><div><Label>Payment mode</Label><select className="mt-1.5 flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm" value={receiptDraft.paymentMode} onChange={(event) => setReceiptDraft((current) => current ? { ...current, paymentMode: event.target.value as ReceiptDraft["paymentMode"] } : current)}><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Card</option><option>Cheque</option><option>Other</option></select></div><div><Label>Transaction reference</Label><Input className="mt-1.5" value={receiptDraft.transactionReference} onChange={(event) => setReceiptDraft((current) => current ? { ...current, transactionReference: event.target.value } : current)} placeholder="Optional" /></div><div className="sm:col-span-2"><Label>Receipt notes</Label><Textarea className="mt-1.5" value={receiptDraft.notes} onChange={(event) => setReceiptDraft((current) => current ? { ...current, notes: event.target.value } : current)} /></div></div><div className="rounded-2xl border border-slate-200 p-5"><div className="flex items-center justify-between border-b border-slate-200 pb-3"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-slate-400">Preview</p><p className="mt-1 text-xl font-serif font-semibold text-slate-800">Payment Receipt</p></div><p className="text-sm font-semibold text-[#4f2ad3]">{client.clientId}</p></div><div className="grid gap-4 py-4 text-sm sm:grid-cols-2"><div><p className="text-xs text-slate-400">Received from</p><p className="font-semibold text-slate-800">{client.clientName}</p><p className="text-slate-600">{client.contactNumber}</p><p className="text-slate-600">{client.email}</p></div><div><p className="text-xs text-slate-400">Payment details</p><p className="text-slate-700">Mode: <strong>{receiptDraft.paymentMode}</strong></p><p className="text-slate-700">Date: <strong>{formatDate(receiptDraft.paymentDate)}</strong></p><p className="text-slate-700">Reference: <strong>{receiptDraft.transactionReference || "—"}</strong></p></div></div><div className="flex items-center justify-between border-y border-slate-200 py-3 text-sm"><span className="font-semibold text-slate-700">{products[receiptDraft.productIndex]?.productName}</span><span className="font-bold text-[#4f2ad3]">{money(receiptDraft.amount)}</span></div><p className="pt-3 text-sm font-semibold text-slate-800">Amount in words: {amountInWords(Number(receiptDraft.amount))}</p></div><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setReceiptDraft(null)}>Cancel</Button><Button onClick={submitReceiptDraft} disabled={createReceipt.isPending}>{createReceipt.isPending ? "Submitting…" : "Submit receipt"}</Button></div></div>}</DialogContent></Dialog></DashboardLayout>;
}
